import{_ as t,o as s,c as o,a7 as a}from"./chunks/framework.C4ZIv4ii.js";const g=JSON.parse('{"title":"Post Views","description":"","frontmatter":{},"headers":[],"relativePath":"guide/post-views.md","filePath":"guide/post-views.md","lastUpdated":1793708106000}'),i={name:"guide/post-views.md"};function n(r,e,d,h,l,c){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="post-views" tabindex="-1">Post Views <a class="header-anchor" href="#post-views" aria-label="Permalink to &quot;Post Views&quot;">​</a></h1><p>Every site counts how many times each post is read <em>(since v2.8.18)</em>. Show the count on a post or a card with the builder&#39;s dynamic content, and order a Card grid by it for &quot;Most read&quot; and &quot;Trending&quot; boxes. No plugin is needed.</p><h2 id="how-a-view-is-counted" tabindex="-1">How a view is counted <a class="header-anchor" href="#how-a-view-is-counted" aria-label="Permalink to &quot;How a view is counted&quot;">​</a></h2><p>The post page reports the view once it has loaded in the reader&#39;s browser.</p><ul><li><strong>It works with the page cache and behind Cloudflare.</strong> A page served from the cache or a CDN counts like any other.</li><li><strong>Bots are left out.</strong> Search engines and monitors that do not run scripts never count, and known bots are filtered by name too.</li><li><strong>A reload is not a new reader.</strong> A visitor counts once per post every 30 minutes.</li><li><strong>Your own team is left out.</strong> Signed-in visitors are not counted.</li><li><strong>Only published posts count</strong>, and only the post type <code>post</code> by default.</li></ul><p>Daily figures are kept for 120 days, so today, the last 7 and the last 30 days stay exact; the all-time count of each post is kept for ever. Old days are pruned every night by <code>falcon:prune-post-views</code>, which runs with the <a href="/falconcms/guide/upgrade.html#scheduled-tasks">scheduler</a>.</p><div class="tip custom-block"><p class="custom-block-title">More control with Falcon News</p><p>The <a href="/falconcms/guide/news.html">Falcon News</a> plugin (Pro) adds a <strong>Most Viewed</strong> screen, a <strong>Views</strong> column in the admin lists, and settings for which post types count, the time before a reader counts again, whether signed-in visitors count and how many days are kept.</p></div><h2 id="showing-a-post-s-view-count" tabindex="-1">Showing a post&#39;s view count <a class="header-anchor" href="#showing-a-post-s-view-count" aria-label="Permalink to &quot;Showing a post&#39;s view count&quot;">​</a></h2><p>Any title, text block or button can show the count. Click the database icon, choose <strong>Post → Post Views</strong>, then pick:</p><ul><li><strong>Period</strong>: all time, today, last 7 or 30 days.</li><li><strong>Number</strong>: <code>12,345</code>, <code>12.3K</code> or <code>12345</code>.</li><li><strong>Label</strong>: the words after the number (<code>views</code>), or around it with <code>{count}</code>: <code>Read {count} times</code>. Leave it empty for the number alone.</li><li><strong>Digits</strong>: Latin, Bangla (<code>১২৩</code>), Devanagari or Arabic.</li><li><strong>Hide below</strong>: show the fallback text instead until a post has this many views.</li></ul><p>It works on a single post layout, in each card of a Card grid, and in the <strong>Post Card</strong> builder <em>(since v2.8.19)</em>, so every card of a blog list can show <code>View: 1,530</code> where it showed the reading time. In text you can also type the token <code>{lazy:post_views}</code>.</p><h2 id="most-read-and-trending-boxes" tabindex="-1">Most Read and Trending boxes <a class="header-anchor" href="#most-read-and-trending-boxes" aria-label="Permalink to &quot;Most Read and Trending boxes&quot;">​</a></h2><p>Add a <strong>Card</strong> element and set <strong>Order By</strong> to one of:</p><table tabindex="0"><thead><tr><th>Order By</th><th>Shows</th></tr></thead><tbody><tr><td>Views</td><td>the most read posts of all time</td></tr><tr><td>Views — today</td><td>today&#39;s most read</td></tr><tr><td>Views — last 7 days</td><td>this week&#39;s trending posts</td></tr><tr><td>Views — last 30 days</td><td>this month&#39;s most read</td></tr></tbody></table><p>Combine it with <strong>Posts By → Categories</strong> for a &quot;Most read in Sports&quot; box.</p><p>In code, the same orders work in <code>get_falcon_posts()</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$trending </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_falcon_posts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;orderby&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;views_week&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;limit&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p><code>orderby</code> takes <code>views</code>, <code>views_day</code>, <code>views_week</code> and <code>views_month</code>.</p><h2 id="moving-from-falcon-news" tabindex="-1">Moving from Falcon News <a class="header-anchor" href="#moving-from-falcon-news" aria-label="Permalink to &quot;Moving from Falcon News&quot;">​</a></h2><p>A site that counted with Falcon News before v2.8.18 keeps its figures: the update copies them, and the counter&#39;s settings, into the core. Falcon News 1.1 and later count through the core, so nothing is counted twice.</p>',20)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
